  if (!best) return null;
  var ok = bestFit.mean <= O.fitMean && bestFit.max <= O.fitMax && bestFit.tail <= O.fitTail;     // \uc9c0\ub098\uc628 \uae38\uacfc \ud604\uc7ac \uc704\uce58\uac00 \ubaa8\ub450 \uadf8 \uacbd\ub85c \uc704\uc5ec\uc57c \ud55c\ub2e4
  if (ok && cur && !(bestFit.mean + O.fitBetterBy < cur.mean)) ok = false;                         // \uc9c0\uae08 \ubcf4\ub358 \uacbd\ub85c\ubcf4\ub2e4 \ud655\uc2e4\ud788 \uc798 \ub9de\uc544\uc57c \ud55c\ub2e4
